import os, sys
from xml.dom import minidom

base = "unpacked_report"
print("=== FILES ===")
for root, dirs, files in os.walk(base):
    for f in sorted(files):
        p = os.path.join(root, f)
        print(p)

print("\n=== DOCUMENT PARAGRAPHS (index | style | text) ===")
doc = minidom.parse(os.path.join(base, "word", "document.xml"))
ns = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"

def local(tag):
    return tag.split("}")[-1]

body = doc.getElementsByTagName("w:body")[0]

def para_text(p):
    parts = []
    for t in p.getElementsByTagName("w:t"):
        parts.append(t.firstChild.data if t.firstChild else "")
    for t in p.getElementsByTagName("w:delText"):
        parts.append("[DEL:" + (t.firstChild.data if t.firstChild else "") + "]")
    return "".join(parts)

def para_style(p):
    ppr = p.getElementsByTagName("w:pPr")
    if ppr:
        st = ppr[0].getElementsByTagName("w:pStyle")
        if st:
            return st[0].getAttribute("w:val")
    return ""

idx = 0
for child in body.childNodes:
    if not hasattr(child, "tagName"):
        continue
    name = local(child.tagName)
    if name == "p":
        txt = para_text(child)
        style = para_style(child)
        print(f"[{idx}] <p style={style!r}> {txt!r}")
        idx += 1
    elif name == "tbl":
        print(f"[{idx}] <TABLE>")
        idx += 1
    elif name == "sectPr":
        print(f"[{idx}] <sectPr>")
        idx += 1
    else:
        print(f"[{idx}] <{name}>")
        idx += 1

print("\n=== STYLES PRESENT (styles.xml) ===")
sp = os.path.join(base, "word", "styles.xml")
if os.path.exists(sp):
    sdoc = minidom.parse(sp)
    for s in sdoc.getElementsByTagName("w:style"):
        sid = s.getAttribute("w:styleId")
        nm = s.getElementsByTagName("w:name")
        nmv = nm[0].getAttribute("w:val") if nm else ""
        print(f"styleId={sid!r} name={nmv!r}")

