# Walk paragraphs in document order
def walk(node, depth=0):
    for child in node.childNodes:
        if child.nodeType != 1:
            continue
        tag = child.tagName
        if tag == "w:p":
            texts = []
            for t in child.getElementsByTagName("w:t"):
                if t.firstChild:
                    texts.append(t.firstChild.data)
            style = ""
            for pPr in child.getElementsByTagName("w:pPr"):
                for pStyle in pPr.getElementsByTagName("w:pStyle"):
                    style = pStyle.getAttribute("w:val")
            txt = "".join(texts)
            print(f"P style={style!r}: {txt[:120]}")
        elif tag == "w:tbl":
            print("TABLE")
        elif tag == "w:sectPr":
            print("SECTPR (end of body)")
        else:
            walk(child, depth + 1)

walk(body)

